UPDATE "model_configs" SET "features" = array_append("features", 'pose_generator') WHERE "id" IN ('nano-banana-2.1', 'nano-banana-2.1-vertex', 'nano-banana-pro', 'nano-banana-pro-vertex') AND NOT ('pose_generator' = ANY("features"));